8	
9	// requireInvalidContinuation pins the public contract for a continuation
10	// whose filter no longer matches the first page: it is an argument problem,
11	// never a chain-data problem, and no page results are observable.
12	func requireInvalidContinuation(t *testing.T, index *Index, query TxQuery) {
13		t.Helper()
14		page, err := index.QueryTxs(query)
15		if !errors.Is(err, ErrInvalidArgument) {
16			t.Fatalf("continuation err=%v, want ErrInvalidArgument", err)
17		}
18		if errors.Is(err, ErrQueryChanged) {
19			t.Fatalf("changed filter spelling reported as ErrQueryChanged: %v", err)
20		}
21		if !reflect.DeepEqual(page, TxPage{}) {
22			t.Fatalf("rejected continuation returned page results: %+v", page)
23		}
24	}
25	
26	// TestQueryTxsFilterSetSpellingAcrossPages protects the rule that only the
27	// set of identifiers matters: reordered, deduplicated or re-duplicated
28	// spellings describe the same filter and must keep working with the original
29	// cursor. Every occurrence survives (including repeats inside one block), in
30	// height/position order, and whole-range statistics stay fixed.
31	func TestQueryTxsFilterSetSpellingAcrossPages(t *testing.T) {
32		index := txChain(t,
33			[]string{"a", "a", "b"},
34			[]string{"a", "", ""},
35			[]string{},
36			[]string{"c", "a", "c", "a"},
37			[]string{"", "a"},
38		)
39		want := []TxHit{
40			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
41			{Height: 1, BlockHash: "h1", TxID: "a", Position: 1},
42			{Height: 2, BlockHash: "h2", TxID: "a", Position: 0},
43			{Height: 4, BlockHash: "h4", TxID: "c", Position: 0},
44			{Height: 4, BlockHash: "h4", TxID: "a", Position: 1},
45			{Height: 4, BlockHash: "h4", TxID: "c", Position: 2},
46			{Height: 4, BlockHash: "h4", TxID: "a", Position: 3},
47			{Height: 5, BlockHash: "h5", TxID: "a", Position: 1},
48		}
49	
50		// First page with a duplicated spelling and a page size of 3.
51		first, err := index.QueryTxs(TxQuery{TxIDs: []string{"a", "c", "a"}, PageSize: 3})
52		if err != nil {
53			t.Fatal(err)
54		}
55		if first.NextCursor == "" {
56			t.Fatal("expected a continuation cursor")
57		}
58		if !reflect.DeepEqual(first.Hits, want[:3]) {
59			t.Fatalf("first page hits=%v, want %v", first.Hits, want[:3])
60		}
61	
62		// Second page: same set reordered and deduplicated, resized to 2.
63		second, err := index.QueryTxs(TxQuery{TxIDs: []string{"c", "a"}, PageSize: 2, Cursor: first.NextCursor})
64		if err != nil {
65			t.Fatalf("reordered, deduplicated set refused: %v", err)
66		}
67		if !reflect.DeepEqual(second.Hits, want[3:5]) {
68			t.Fatalf("second page hits=%v, want %v", second.Hits, want[3:5])
69		}
70		if second.NextCursor == "" {
71			t.Fatal("expected another continuation cursor")
72		}
73	
74		// Third page: same set with extra duplicates, resized to 3; it is last.
75		third, err := index.QueryTxs(TxQuery{TxIDs: []string{"c", "c", "a", "a"}, PageSize: 3, Cursor: second.NextCursor})
76		if err != nil {
77			t.Fatalf("re-duplicated set refused: %v", err)
78		}
