97		// Cross-check: a single page over the same range must list exactly the
98		// same occurrences, proving repeats within a block were not merged and
99		// positions follow the original transaction list.
100		single, err := index.QueryTxs(TxQuery{TxIDs: []string{"c", "a", "c"}, PageSize: MaxPageSize})
101		if err != nil {
102			t.Fatal(err)
103		}
104		if !reflect.DeepEqual(single.Hits, want) {
105			t.Fatalf("single-page hits=%v, want %v", single.Hits, want)
106		}
107	}
