109	// TestQueryTxsEmptySetAndEmptyIDDiffer protects three distinct meanings:
110	// no TxIDs field, an explicitly empty slice (both mean "no filter") and a
111	// set containing the empty string (only empty-identifier occurrences).
112	func TestQueryTxsEmptySetAndEmptyIDDiffer(t *testing.T) {
113		index := txChain(t,
114			[]string{"a", ""},
