279		// Rejected continuations are read-only; the main chain is untouched.
280		requireUnchanged(t, index, blocks, byHash, tip)
281	
282		// The original set, reordered, still reads the original next page.
283		second, err := index.QueryTxs(TxQuery{TxIDs: []string{"b", "a"}, PageSize: 3, Cursor: first.NextCursor})
284		if err != nil {
