package indexroom

import (
	"fmt"
)

// MaxTimeBuckets is the largest number of segments one QueryTimeStats call
// may return.
const MaxTimeBuckets = 10000

// statsQueryHookLocked is a test-only rendezvous invoked once per
// QueryTimeStats call while index.mu is held, with the resolved tip-bound
// height (after clamping, before any block is scanned). It is nil in
// production; reorg regression tests set it to park a query that has already
// pinned its height range with the lock held, forcing a concurrent Reorg to
// wait and making the "one complete main-chain state" observation
// deterministic instead of relying on scheduling luck.
var statsQueryHookLocked func(resolvedTo int64)

// TimeStatsQuery asks for transaction statistics over a half-open time
// window, segmented into fixed-length buckets.
//
// From and To reuse the TxQuery height semantics: heights are inclusive, a
// zero From starts at height 1, a zero To pins the chain tip, and an
// explicit To above the tip is clamped to it. TxIDs reuses the exact-string
// filter semantics, including duplicates and empty identifiers.
//
// Start and End are Unix seconds bounding the window [Start, End): Start is
// included, End is excluded. Both must be non-negative and Start must be
// below End. StepSeconds is the bucket length in seconds and must be
// positive; buckets start at Start and the final bucket is cut off at End.
// Times outside any int64 range cannot be requested.
type TimeStatsQuery struct {
	From        int64
	To          int64
	TxIDs       []string
	Start       int64
	End         int64
	StepSeconds int64
}

// TimeBucket is statistics for one half-open segment [Start, End). Buckets
// with no matching transactions are returned with every count at zero.
type TimeBucket struct {
	Start int64
	End   int64
	// TxCount counts matching transaction occurrences in the segment.
	TxCount int64
	// DistinctTxIDs counts the different matching identifiers in the segment.
	DistinctTxIDs int64
	// Blocks counts blocks whose timestamp falls in the segment and which
	// hold at least one matching transaction.
	Blocks int64
}

// TimeTotals summarizes the whole window with the same counters as a bucket.
// DistinctTxIDs is deduplicated over the whole window, not summed from the
// per-bucket values.
type TimeTotals struct {
	TxCount       int64
	DistinctTxIDs int64
	Blocks        int64
}

// TimeStats is the result of QueryTimeStats. Buckets are ordered by ascending
// time and always cover the whole requested window, even on an empty chain,
// above the chain tip, or when nothing matches. MissingTimeBlocks reports how
// many blocks in the resolved height range carry no timestamp; those blocks
// never enter a bucket, and the count ignores the transaction filter.
type TimeStats struct {
	Buckets []TimeBucket
	Totals  TimeTotals
	// FromHeight and ToHeight are the resolved inclusive height bounds,
	// clamped to the chain tip observed by this call.
	FromHeight int64
	ToHeight   int64
	// MissingTimeBlocks counts blocks in [FromHeight, ToHeight] without a
	// timestamp, regardless of the transaction filter.
	MissingTimeBlocks int64
}

// QueryTimeStats buckets matching transactions by block timestamp over the
// requested height range. The call observes one complete main-chain state:
// concurrent Append, Reorg, or Restore calls never mix old and new blocks
// into the answer, and the index is never modified.
func (index *Index) QueryTimeStats(query TimeStatsQuery) (TimeStats, error) {
	from, to, err := normalizeRange(query.From, query.To)
	if err != nil {
		return TimeStats{}, err
	}
	if query.Start < 0 {
		return TimeStats{}, fmt.Errorf("%w: start time must not be negative", ErrInvalidArgument)
	}
	if query.End < 0 {
		return TimeStats{}, fmt.Errorf("%w: end time must not be negative", ErrInvalidArgument)
	}
	if query.Start >= query.End {
		return TimeStats{}, fmt.Errorf("%w: start time must be below end time", ErrInvalidArgument)
	}
	if query.StepSeconds <= 0 {
		return TimeStats{}, fmt.Errorf("%w: step seconds must be positive", ErrInvalidArgument)
	}

	// Window length is positive and bounded by MaxInt64 since End > Start.
	width := query.End - query.Start
	count := width / query.StepSeconds
	if width%query.StepSeconds != 0 {
		count++
	}
	if count > MaxTimeBuckets {
		return TimeStats{}, fmt.Errorf("%w: time window would produce %d buckets, limit is %d",
			ErrInvalidArgument, count, MaxTimeBuckets)
	}

	filter := newTxFilter(query.TxIDs)

	stats := TimeStats{Buckets: make([]TimeBucket, count)}
	for i := range stats.Buckets {
		stats.Buckets[i].Start = bucketBoundary(query.Start, query.StepSeconds, int64(i))
		// A saturated boundary (MaxInt64) and the overshooting final step
		// are both cut back to the requested window end.
		end := bucketBoundary(query.Start, query.StepSeconds, int64(i)+1)
		if end > query.End {
			end = query.End
		}
		stats.Buckets[i].End = end
	}

	index.mu.Lock()
	defer index.mu.Unlock()

	if to == 0 || to > index.Tip {
		to = index.Tip
	}
	stats.FromHeight = from
	stats.ToHeight = to
	if from > to {
		// Empty index or a start above the tip: zeroed buckets are still
		// returned for the whole requested window.
		return stats, nil
	}

	if statsQueryHookLocked != nil {
		statsQueryHookLocked(to)
	}

	distinct := make([]map[string]struct{}, count)
	windowDistinct := make(map[string]struct{})
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		if block.Time == nil {
			stats.MissingTimeBlocks++
			continue
		}
		t := *block.Time
		if t < query.Start || t >= query.End {
			continue
		}
		bucket := (t - query.Start) / query.StepSeconds
		matched := false
		for _, tx := range block.Txs {
			if filter != nil {
				if _, ok := filter[tx]; !ok {
					continue
				}
			}
			stats.Buckets[bucket].TxCount++
			stats.Totals.TxCount++
			if distinct[bucket] == nil {
				distinct[bucket] = make(map[string]struct{})
			}
			distinct[bucket][tx] = struct{}{}
			windowDistinct[tx] = struct{}{}
			matched = true
		}
		if matched {
			stats.Buckets[bucket].Blocks++
			stats.Totals.Blocks++
		}
	}
	for i := range distinct {
		stats.Buckets[i].DistinctTxIDs = int64(len(distinct[i]))
	}
	stats.Totals.DistinctTxIDs = int64(len(windowDistinct))
	return stats, nil
}

// bucketBoundary returns Start + step*index, saturated at MaxInt64 instead
// of overflowing. Callers cut saturated and trailing boundaries back to the
// requested window end.
func bucketBoundary(start, step, index int64) int64 {
	offset := saturatingMul(step, index)
	if offset > 1<<63-1-start {
		return 1<<63 - 1
	}
	return start + offset
}

// saturatingMul multiplies non-negative a and b, saturating at MaxInt64.
func saturatingMul(a, b int64) int64 {
	if a == 0 || b == 0 {
		return 0
	}
	if a > (1<<63-1)/b {
		return 1<<63 - 1
	}
	return a * b
}

package indexroom

import (
	"fmt"
	"reflect"
	"testing"
)

// referenceScan independently computes the full filtered occurrence list and
// matched-block count for [from, to], the same way the old collectLocked did,
// so the page-sized scan can be compared against an oracle that keeps every
// record.
func referenceScan(index *Index, from, to int64, txIDs []string) ([]TxHit, int64) {
	filter := map[string]struct{}{}
	for _, id := range txIDs {
		filter[id] = struct{}{}
	}
	var all []TxHit
	var blocks int64
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		matched := false
		for position, tx := range block.Txs {
			if len(txIDs) > 0 {
				if _, ok := filter[tx]; !ok {
					continue
				}
			}
			all = append(all, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
			matched = true
		}
		if matched {
			blocks++
		}
	}
	return all, blocks
}

// TestScanPageLockedRetainsOnlyPageWindow is the memory contract behind the
// QueryTxs refactor: a scan may keep at most pageSize TxHit records no matter
// how many matches the pinned range holds, while totals still describe the
// whole range and every offset slices the same ordered occurrence list the
// old full-materialization scan would have produced.
func TestScanPageLockedRetainsOnlyPageWindow(t *testing.T) {
	// 60 blocks, three txs each with repeated identifiers: 180 occurrences.
	var blocks [][]string
	for h := 0; h < 60; h++ {
		blocks = append(blocks, []string{
			fmt.Sprintf("t%d", h%5), // five ids cycling: selective filter
			"keep",
			"keep", // same id twice in one block: both occurrences survive
		})
	}
	index := txChain(t, blocks...)

	const from, to = int64(1), int64(60)
	all, matchedBlocks := referenceScan(index, from, to, nil)
	if len(all) != 180 || matchedBlocks != 60 {
		t.Fatalf("oracle setup: hits=%d blocks=%d, want 180/60", len(all), matchedBlocks)
	}

	for _, pageSize := range []int{1, 2, 7, DefaultPageSize, MaxPageSize} {
		var windowed []TxHit
		for offset := int64(0); ; {
			hits, total, gotBlocks := index.scanPageLocked(from, to, nil, offset, pageSize)
			if total != int64(len(all)) {
				t.Fatalf("pageSize=%d offset=%d: total=%d, want whole-range %d", pageSize, offset, total, len(all))
			}
			if gotBlocks != matchedBlocks {
				t.Fatalf("pageSize=%d offset=%d: blocks=%d, want %d", pageSize, offset, gotBlocks, matchedBlocks)
			}
			if len(hits) > pageSize || cap(hits) > pageSize {
				t.Fatalf("pageSize=%d offset=%d: scan retained len=%d cap=%d records, want at most %d",
					pageSize, offset, len(hits), cap(hits), pageSize)
			}
			end := offset + int64(len(hits))
			if end > int64(len(all)) || !reflect.DeepEqual(hits, all[offset:end]) {
				t.Fatalf("pageSize=%d offset=%d: window does not match the full occurrence slice", pageSize, offset)
			}
			windowed = append(windowed, hits...)
			if len(hits) < pageSize {
				break // last, possibly partial page
			}
			offset = end
		}
		if !reflect.DeepEqual(windowed, all) {
			t.Fatalf("pageSize=%d: walking windows lost or duplicated occurrences", pageSize)
		}
	}

	// A selective filter keeps the same contract on the filtered answer.
	filtered, filteredBlocks := referenceScan(index, from, to, []string{"keep", "t1"})
	hits, total, gotBlocks := index.scanPageLocked(from, to, []string{"t1", "keep", "keep"}, 3, 5)
	if total != int64(len(filtered)) || gotBlocks != filteredBlocks {
		t.Fatalf("filtered totals=%d/%d, want %d/%d", total, gotBlocks, len(filtered), filteredBlocks)
	}
	if !reflect.DeepEqual(hits, filtered[3:8]) {
		t.Fatalf("filtered window=%v, want %v", hits, filtered[3:8])
	}
	if cap(hits) > 5 {
		t.Fatalf("filtered scan retained cap=%d, want at most 5", cap(hits))
	}

	// An offset beyond the matches keeps whole-range statistics but returns no
	// records; the continuation caller turns this into ErrQueryChanged.
	hits, total, gotBlocks = index.scanPageLocked(from, to, nil, int64(len(all))+10, 4)
	if len(hits) != 0 || total != int64(len(all)) || gotBlocks != matchedBlocks {
		t.Fatalf("beyond-end scan: hits=%d total=%d blocks=%d", len(hits), total, gotBlocks)
	}

	// An empty range retains nothing and reports zero statistics.
	hits, total, gotBlocks = index.scanPageLocked(100, 200, nil, 0, 10)
	if len(hits) != 0 || cap(hits) > 10 || total != 0 || gotBlocks != 0 {
		t.Fatalf("empty-range scan: hits=%v total=%d blocks=%d", hits, total, gotBlocks)
	}
}

// TestQueryTxsTemporaryRecordsDoNotScaleWithTotal is an end-to-end check that
// paging through a range with a tiny page size and a huge hit total works
// identically whether the answer is read in one page or many: the temporary
// footprint shrinks with the page size while all visible behavior is fixed.
func TestQueryTxsTemporaryRecordsDoNotScaleWithTotal(t *testing.T) {
	var blocks [][]string
	for h := 0; h < 40; h++ {
		blocks = append(blocks, []string{"a", "b", "c", "d", "e"})
	}
	index := txChain(t, blocks...) // 200 matches

	full, err := index.QueryTxs(TxQuery{PageSize: MaxPageSize})
	if err != nil {
		t.Fatal(err)
	}
	if full.TotalMatches != 200 || full.MatchedBlocks != 40 {
		t.Fatalf("unexpected totals: %+v", full)
	}

	// Page size 1: 200 round trips, each retaining one hit while scanning.
	pages := collectPages(t, index, TxQuery{PageSize: 1})
	if len(pages) != 200 {
		t.Fatalf("pages=%d, want 200", len(pages))
	}
	var all []TxHit
	for i, page := range pages {
		if page.TotalMatches != 200 || page.MatchedBlocks != 40 || page.ToHeight != 40 {
			t.Fatalf("page %d statistics describe the page instead of the range: %+v", i, page)
		}
		if i < len(pages)-1 && len(page.Hits) != 1 {
			t.Fatalf("page %d holds %d hits, want exactly one", i, len(page.Hits))
		}
		if i < len(pages)-1 && page.NextCursor == "" {
			t.Fatalf("page %d unexpectedly the last", i)
		}
		all = append(all, page.Hits...)
	}
	if pages[len(pages)-1].NextCursor != "" {
		t.Fatalf("last page must carry an empty cursor, got %q", pages[len(pages)-1].NextCursor)
	}
	if len(all) != 200 {
		t.Fatalf("collected %d hits, want 200", len(all))
	}
	// The single large-page answer spans the same ordered occurrences.
	if full.NextCursor != "" || len(full.Hits) != 200 {
		t.Fatalf("unexpected large page: %d hits cursor=%q", len(full.Hits), full.NextCursor)
	}
	if !reflect.DeepEqual(all, full.Hits) {
		t.Fatalf("page-size-1 walk differs from the full answer")
	}
}

